"""Member workspace shells. Private records are fetched only after sign in."""

def build_members(page):
    page('community/members', 'Your Workshop', 'A private member workspace for shared learning, introductions and scoped reviews.', '''
<link rel="stylesheet" href="/assets/community/members.css">
<div class="member-heading"><div><p class="eyebrow">The Workshop · Member pilot</p><h1>Make useful<br>connections.</h1><p class="lede">Bring a question. Share a skill. Agree on one next step.</p></div><button id="member-signout" class="button secondary" type="button" hidden>Sign out</button></div>
<p id="member-status" class="status member-status" role="status" aria-live="polite" tabindex="-1">Sign in to open your private workspace.</p>
<section id="member-login-panel" class="member-login-grid">
<div class="panel"><p class="eyebrow">Already invited?</p><h2>Member sign in</h2><form id="member-login"><div class="field"><label for="member-email">Email address</label><input id="member-email" name="email" type="email" autocomplete="username" maxlength="254" required></div><div class="field"><label for="member-password">Password</label><input id="member-password" name="password" type="password" autocomplete="current-password" required></div><button type="submit">Sign in privately</button></form><p class="small">Your session stays in this tab for up to 30 minutes. Reloading signs you out. Your password and access token are never saved in browser storage.</p></div>
<div class="panel member-welcome"><p class="eyebrow">Small beginnings. Deliberate choices.</p><h2>A place to work together.</h2><ul class="member-benefits"><li>Choose what appears in your profile.</li><li>Find people with shared interests.</li><li>Agree to introductions and review assignments.</li><li>Publish feedback only after a separate choice.</li></ul><p>The pilot is invitation only. Joining an email list does not create a member account or grant a professional credential.</p><details id="member-create-panel"><summary>Use a pilot invitation</summary><form id="member-create"><div class="field"><label for="create-token">Private invitation code</label><input id="create-token" name="invite_token" type="password" autocomplete="off" minlength="64" maxlength="64" pattern="[a-f0-9]{64}" required></div><div class="field"><label for="create-email">Email address</label><input id="create-email" name="email" type="email" autocomplete="email" maxlength="254" required></div><div class="field"><label for="create-name">Display name</label><input id="create-name" name="display_name" autocomplete="nickname" maxlength="60" required></div><div class="field"><label for="create-password">New password</label><input id="create-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required><p class="small">Use at least 12 characters and a password you do not use elsewhere.</p></div><label class="check"><input type="checkbox" name="adult" required><span>I am 18 or older.</span></label><label class="check"><input type="checkbox" name="privacy_acknowledged" required><span>I have read the <a href="/community/privacy/">privacy notice</a> and understand this is a limited member pilot.</span></label><button type="submit">Create invited account</button></form></details><p><a href="/join/">Choose email updates</a> · <a href="/community/voices/">Read published feedback</a></p></div>
</section>
<section id="member-join-panel" class="panel" hidden><h2>Accept your invitation</h2><p>Your account is signed in. Use your private invitation to join this pilot.</p><form id="member-join"><div class="field"><label for="join-token">Private invitation code</label><input id="join-token" name="invite_token" type="password" autocomplete="off" minlength="64" maxlength="64" pattern="[a-f0-9]{64}" required></div><div class="field"><label for="join-name">Display name</label><input id="join-name" name="display_name" autocomplete="nickname" maxlength="60" required></div><label class="check"><input type="checkbox" name="adult" required><span>I am 18 or older.</span></label><label class="check"><input type="checkbox" name="privacy_acknowledged" required><span>I have read the <a href="/community/privacy/">privacy notice</a> and understand this limited pilot.</span></label><button type="submit">Join the Workshop</button></form></section>
<div id="member-workspace" hidden>
<div class="member-workspace-bar"><p id="member-welcome" class="member-welcome-line"></p><button id="member-refresh" class="button secondary" type="button">Refresh workspace</button></div>
<nav id="member-navigation" class="member-tabs" aria-label="Member workspace"></nav>
<p id="member-access-note" class="member-note" hidden></p>
<div class="member-boundary"><strong>Keep real case records private.</strong> Use broad, non-identifying descriptions here. Do not post names of children, case numbers, sealed records or private addresses. This workspace does not provide legal advice.</div>
<div id="member-sections"></div>
</div>
<noscript><p>JavaScript is required to sign in. No member records are embedded in this page.</p></noscript>
''', 'members.js')
    page('community/voices', 'Shared in their own words', 'Feedback and credentials published with separate permission and human review.', '''
<link rel="stylesheet" href="/assets/community/members.css">
<section class="member-public-intro"><p class="eyebrow">The Workshop · Public voices</p><h1>Shared by choice.</h1><p class="lede">Feedback offered in members’ own words. Credentials with a stated source and review status.</p><p>Publication is optional and separate from getting help or taking part. Members can withdraw permission. A credential review has a limited scope; it does not guarantee a person’s work or confer authority.</p></section>
<p id="voices-status" class="status" role="status" aria-live="polite">Checking published contributions…</p>
<div id="member-voices"><section class="section-block"><h2>Member feedback</h2><div id="voices-feedback" class="member-card-grid"></div></section><section class="section-block"><h2>Credential statements</h2><div id="voices-credentials" class="member-card-grid"></div></section></div>
<p><a class="button secondary" href="/community/members/">Open your member workspace</a></p><noscript><p>Enable JavaScript to load current published contributions. Only records with current publication permission and approval appear.</p></noscript>
''', 'members.js')
